// Official basalt-headers aa441ba3 and Eigen 5.0.1.
#include <sophus/se3.hpp>
#include <basalt/spline/se3_spline.h>
#include <basalt/spline/ceres_spline_helper.h>
#include <nlohmann/json.hpp>
#include <iostream>
using Json=nlohmann::json;
template<class M>Json matrix(const M&m){Json out=Json::array();for(int r=0;r<m.rows();++r)for(int c=0;c<m.cols();++c)out.push_back(m(r,c));return out;}
template<int N>Json run(){basalt::Se3Spline<N,double>spline(20000000,1000000000);for(int i=0;i<N+3;++i)spline.knotsPushBack(Sophus::SE3d(Sophus::SO3d::exp(Eigen::Vector3d(.025*i,-.015*i*i,.01*(i%3))),Eigen::Vector3d(.125*i,.0625*i*i,-.03125*i)));Json out=Json::array();for(int64_t time:{1000000000LL,1007000000LL,1020000000LL,1079999999LL}){typename basalt::Se3Spline<N,double>::PosePosSO3JacobianStruct pose_j;typename basalt::Se3Spline<N,double>::SO3JacobianStruct gyro_j,orientation_j;typename basalt::Se3Spline<N,double>::AccelPosSO3JacobianStruct accel_j;typename basalt::Se3Spline<N,double>::PosJacobianStruct position_j;Eigen::Matrix<double,3,12>gyro_bias_j;Eigen::Matrix<double,3,9>accel_bias_j;Eigen::Matrix3d gravity_j;Eigen::Matrix<double,6,1>time_j;basalt::CalibAccelBias<double>accel_bias;basalt::CalibGyroBias<double>gyro_bias;Eigen::Vector3d measurement(.1,-.2,.3),gravity(0,0,-9.81);auto pose=spline.pose(time,&pose_j);auto gyro=spline.gyroResidual(time,measurement,gyro_bias,&gyro_j,&gyro_bias_j);auto accel=spline.accelResidual(time,measurement,accel_bias,gravity,&accel_j,&accel_bias_j,&gravity_j);auto position=spline.positionResidual(time,measurement,&position_j);auto orientation=spline.orientationResidual(time,Sophus::SO3d::exp(measurement),&orientation_j);spline.d_pose_d_t(time,time_j);Json item={{"time",time},{"pose",matrix(pose.matrix())},{"time_jacobian",matrix(time_j)},{"gyro",matrix(gyro)},{"accel",matrix(accel)},{"position",matrix(position)},{"orientation",matrix(orientation)},{"gyro_bias_jacobian",matrix(gyro_bias_j)},{"accel_bias_jacobian",matrix(accel_bias_j)},{"gravity_jacobian",matrix(gravity_j)}};for(int i=0;i<N;++i){item["pose_jacobian"].push_back(matrix(pose_j.d_val_d_knot[i]));item["gyro_jacobian"].push_back(matrix(gyro_j.d_val_d_knot[i]));item["accel_jacobian"].push_back(matrix(accel_j.d_val_d_knot[i]));item["position_jacobian"].push_back(position_j.d_val_d_knot[i]);item["orientation_jacobian"].push_back(matrix(orientation_j.d_val_d_knot[i]));}out.push_back(item);}return out;}
template<int N,template<class>class Group>Json lie(){std::array<Group<double>,N>knots;std::array<const double*,N>pointers;for(int i=0;i<N;++i){typename Group<double>::Tangent tangent;for(int k=0;k<tangent.size();++k)tangent[k]=.025*i*(k+1);knots[i]=Group<double>::exp(tangent);pointers[i]=knots[i].data();}Json out=Json::array();for(double u:{0.,.35,.99999995}){Group<double>transform;typename Group<double>::Tangent velocity,acceleration,jerk;basalt::CeresSplineHelper<N>::template evaluate_lie<double,Group>(pointers.data(),u,50.,&transform,&velocity,&acceleration,&jerk);out.push_back({{"u",u},{"transform",matrix(transform.matrix())},{"velocity",matrix(velocity)},{"acceleration",matrix(acceleration)},{"jerk",matrix(jerk)}});}return out;}
Json euclidean(){std::array<Eigen::Vector3d,4>knots;std::array<const double*,4>pointers;for(int i=0;i<4;++i){knots[i]<<.125*i,.0625*i*i,-.03125*i;pointers[i]=knots[i].data();}Json result=Json::array();for(double u:{0.,.35,.99999995}){Eigen::Vector3d value,velocity,acceleration,jerk;basalt::CeresSplineHelper<4>::evaluate<double,3,0>(pointers.data(),u,50.,&value);basalt::CeresSplineHelper<4>::evaluate<double,3,1>(pointers.data(),u,50.,&velocity);basalt::CeresSplineHelper<4>::evaluate<double,3,2>(pointers.data(),u,50.,&acceleration);basalt::CeresSplineHelper<4>::evaluate<double,3,3>(pointers.data(),u,50.,&jerk);result.push_back({{"u",u},{"value",matrix(value)},{"velocity",matrix(velocity)},{"acceleration",matrix(acceleration)},{"jerk",matrix(jerk)}});}return result;}
Json group_ops(){Json result=Json::array();for(double angle:{0.,1e-14,1e-6,3.141592653589793}){Eigen::Matrix<double,6,1> tangent;tangent<<.125,-.25,.375,angle,0.,0.;auto group=Sophus::SE3d::exp(tangent);result.push_back({{"tangent",matrix(tangent)},{"matrix",matrix(group.matrix())},{"log",matrix(group.log())}});}return result;}
int main(){std::cout<<Json({{"se3_4",run<4>()},{"se3_5",run<5>()},{"helper_so3_4",lie<4,Sophus::SO3>()},{"helper_se3_4",lie<4,Sophus::SE3>()},{"helper_rd_4",euclidean()},{"group_ops",group_ops()}}).dump()<<'\n';}
